function floydWarshall(graph){
  const V=graph.length;const dist=graph.map(row=>[...row]);
  for(let i=0;i<V;i++)for(let j=0;j<V;j++){if(i===j)dist[i][j]=0;else if(dist[i][j]===undefined||dist[i][j]===null||dist[i][j]!==dist[i][j])dist[i][j]=Infinity;}
  for(let k=0;k<V;k++)for(let i=0;i<V;i++)for(let j=0;j<V;j++)if(dist[i][k]+dist[k][j]<dist[i][j])dist[i][j]=dist[i][k]+dist[k][j];
  for(let i=0;i<V;i++)if(dist[i][i]<0)return null;
  return dist;
}
const floydWarshallImpl=floydWarshall;

function findTheCityImpl(n,edges,distanceThreshold){
  const dist=Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>i===j?0:Infinity));
  for(const[u,v,w]of edges){dist[u][v]=w;dist[v][u]=w;}
  for(let k=0;k<n;k++)for(let i=0;i<n;i++)for(let j=0;j<n;j++)dist[i][j]=Math.min(dist[i][j],dist[i][k]+dist[k][j]);
  let result=0,minCount=Infinity;
  for(let i=0;i<n;i++){const count=dist[i].filter((d,j)=>j!==i&&d<=distanceThreshold).length;if(count<=minCount){minCount=count;result=i;}}
  return result;
}

