function tarjanSCC(n,edges){
  const adj=Array.from({length:n},()=>[]);for(const[u,v]of edges)adj[u].push(v);
  const disc=new Array(n).fill(-1),low=new Array(n).fill(-1),onStack=new Array(n).fill(false);
  const stack=[],sccs=[];let timer=0;
  function dfs(v){disc[v]=low[v]=timer++;stack.push(v);onStack[v]=true;
    for(const u of adj[v]){if(disc[u]===-1){dfs(u);low[v]=Math.min(low[v],low[u]);}else if(onStack[u])low[v]=Math.min(low[v],disc[u]);}
    if(low[v]===disc[v]){const scc=[];let w;do{w=stack.pop();onStack[w]=false;scc.push(w);}while(w!==v);sccs.push(scc);}
  }
  for(let v=0;v<n;v++)if(disc[v]===-1)dfs(v);return sccs;
}
const tarjanSCCImpl=tarjanSCC;

