function findBridgesAndArticulations(n,edges){
  const adj=Array.from({length:n},()=>[]);for(const[u,v]of edges){adj[u].push(v);adj[v].push(u);}
  const disc=new Array(n).fill(-1),low=new Array(n).fill(-1);
  const bridges=[],artPoints=new Set();let timer=0;
  function dfs(v,parent){
    disc[v]=low[v]=timer++;let childCount=0;
    for(const u of adj[v]){if(u===parent)continue;if(disc[u]===-1){childCount++;dfs(u,v);low[v]=Math.min(low[v],low[u]);if(low[u]>disc[v])bridges.push([v,u]);if(disc[v]!==0&&low[u]>=disc[v])artPoints.add(v);}else low[v]=Math.min(low[v],disc[u]);}
    if(disc[v]===0&&childCount>=2)artPoints.add(v);
  }
  for(let v=0;v<n;v++)if(disc[v]===-1)dfs(v,-1);
  return{bridges,artPoints:[...artPoints]};
}
function criticalConnectionsImpl(n,connections){return findBridgesAndArticulations(n,connections).bridges;}
function findArticulationPoints(n,edges){return findBridgesAndArticulations(n,edges).artPoints;}

