function maxBipartiteMatching(leftCount,rightCount,edges){
  const adj=Array.from({length:leftCount},()=>[]);for(const[l,r]of edges)adj[l].push(r);
  const matchL=new Array(leftCount).fill(-1),matchR=new Array(rightCount).fill(-1);
  function dfs(u,visited){for(const v of adj[u]){if(visited[v])continue;visited[v]=true;if(matchR[v]===-1||dfs(matchR[v],visited)){matchL[u]=v;matchR[v]=u;return true;}}return false;}
  let matching=0;for(let u=0;u<leftCount;u++){const visited=new Array(rightCount).fill(false);if(dfs(u,visited))matching++;}
  return{matching,matchL,matchR};
}
const maxBipartiteMatchingImpl=maxBipartiteMatching;

