const MODULE4=[{id:1334,algorithm:'Floyd-Warshall',nc150:true},{id:1192,algorithm:'Bridge finding DFS',nc150:true},{id:1579,algorithm:'Dual Union-Find',nc150:false}];

function selectAdvancedGraph(signal){
  if(signal.includes('all-pairs')||signal.includes('apsp'))return'Floyd-Warshall';
  if(signal.includes('strongly connected')||signal.includes('scc'))return"Tarjan's SCC";
  if(signal.includes('critical')||signal.includes('bridge'))return'Bridge Finding DFS';
  if(signal.includes('assignment')||signal.includes('matching'))return'Bipartite Matching';
  if(signal.includes('capacity')||signal.includes('flow'))return'Max Flow Edmonds-Karp';
  return'Unknown';
}

function module4Summary(){
  return{total:MODULE4.length,nc150:MODULE4.filter(p=>p.nc150).length};
}
